import{_ as r,C as a,o as s,c as n,a6 as t,E as i}from"./chunks/framework.BJFjZBwW.js";const f=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1785770623000}'),l={name:"getting-started.md"};function h(d,e,g,p,u,c){const o=a("OmgPipeline");return s(),n("div",null,[e[0]||(e[0]=t('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This guide walks you through the two most popular setups from start to finish, flashed <strong>from your browser</strong> and integrated with <strong>Home Assistant</strong>. No soldering, no development environment, about 15 minutes:</p><ul><li><strong>Bluetooth sensors</strong> — any ESP32 board reading thermometers, plant sensors, scales...</li><li><strong>RF devices (433/315/868/915MHz)</strong> — a LILYGO LoRa32 board receiving weather stations, door sensors, PIR sensors...</li></ul><p>Using another controller (OpenHAB, Node-RED...) or another technology (IR, LoRa)? Follow the same steps and take the detours linked along the way.</p><h2 id="how-the-pieces-fit-together" tabindex="-1">How the pieces fit together <a class="header-anchor" href="#how-the-pieces-fit-together" aria-label="Permalink to &quot;How the pieces fit together&quot;">​</a></h2><p>OpenMQTTGateway (OMG) is a firmware for your board that translates signals from your devices (Bluetooth sensors, RF remotes, weather stations...) into MQTT messages, and the other way around:</p>',6)),i(o),e[1]||(e[1]=t('<p>The <strong>broker</strong> is the message hub; the <strong>controller</strong> is the home automation software where you see and use the data.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li><strong>A board</strong> — for <strong>Bluetooth</strong>, any ESP32 development board. For <strong>RF</strong>, a LILYGO® LoRa32 V2.1 or a Heltec LoRa V2 matching your devices&#39; frequency — 433MHz for most European devices, 915MHz in North America (no soldering needed). See the <a href="./prerequisites/board.html">board guide</a> for other cases, or get a pre-flashed <a href="https://shop.theengs.io/" target="_blank" rel="noreferrer">Theengs Bridge</a> and skip the flashing step.</li><li><strong>A data USB cable</strong> — some cables are charge-only and won&#39;t work.</li><li><strong>An MQTT broker</strong> — see Step 1.</li><li><strong>A device to observe</strong> — e.g. a <a href="https://decoder.theengs.io/devices/devices.html" target="_blank" rel="noreferrer">compatible Bluetooth sensor</a> such as a Mi Flora, LYWSD03MMC, Govee or Inkbird thermometer, or any RF sensor around you (weather station, door or PIR sensor...).</li></ul><h2 id="step-1-—-set-up-the-mqtt-broker" tabindex="-1">Step 1 — Set up the MQTT broker <a class="header-anchor" href="#step-1-—-set-up-the-mqtt-broker" aria-label="Permalink to &quot;Step 1 — Set up the MQTT broker&quot;">​</a></h2><p>If you use <strong>Home Assistant</strong>, the simplest option is the Mosquitto add-on:</p><ol><li>In Home Assistant go to <strong>Settings → Add-ons → Add-on store</strong>, install <strong>Mosquitto broker</strong> and start it.</li><li>Install the <strong>MQTT integration</strong> (<strong>Settings → Devices &amp; services → Add integration → MQTT</strong>) if it isn&#39;t set up already.</li><li>Create a dedicated user for the gateway in <strong>Settings → People → Users</strong> (e.g. <code>omg</code> — it doesn&#39;t need to be an administrator). The gateway will log in with it.</li></ol><p>No Home Assistant? Install <a href="https://mosquitto.org/" target="_blank" rel="noreferrer">Mosquitto</a> on any always-on machine, or see the <a href="./prerequisites/broker.html">broker page</a> for alternatives.</p><h2 id="step-2-—-flash-the-firmware-from-your-browser" tabindex="-1">Step 2 — Flash the firmware from your browser <a class="header-anchor" href="#step-2-—-flash-the-firmware-from-your-browser" aria-label="Permalink to &quot;Step 2 — Flash the firmware from your browser&quot;">​</a></h2><ol><li>Open the <a href="./upload/web-install.html">web installer</a> in <strong>Chrome, Edge or Opera</strong> (Firefox and Safari don&#39;t support web flashing).</li><li>Connect the board to your computer with the USB cable.</li><li>Pick the firmware matching your board and use case — the two most flashed: <ul><li><strong>Bluetooth</strong> on a generic ESP32: <a href="./upload/board-selector.html?env=esp32dev-ble"><strong>esp32dev-ble</strong></a></li><li><strong>RF</strong> on a LILYGO LoRa32: <a href="./upload/board-selector.html?env=lilygo-rtl_433"><strong>lilygo-rtl_433</strong></a> (the radio frequency is configurable afterwards)</li></ul></li><li>Click <strong>Connect</strong>, select the board&#39;s USB port, and let the installer finish.</li></ol><p>Prefer a desktop tool, or need a custom configuration? See the other <a href="./upload/">upload options</a>.</p><h2 id="step-3-—-connect-the-gateway-to-your-wifi-and-broker" tabindex="-1">Step 3 — Connect the gateway to your WiFi and broker <a class="header-anchor" href="#step-3-—-connect-the-gateway-to-your-wifi-and-broker" aria-label="Permalink to &quot;Step 3 — Connect the gateway to your WiFi and broker&quot;">​</a></h2><p>After flashing, the gateway starts its own WiFi access point:</p><ol><li>From your phone or computer, connect to the WiFi network named <strong>OpenMQTTGateway</strong> or starting with <strong>OMG_</strong> (no password, except for Theengs devices — see the <a href="./upload/portal.html">portal page</a>).</li><li>A configuration page opens (on Android, accept &quot;stay connected without internet&quot;). Click <strong>Configure WiFi</strong>.</li><li>Select your WiFi network and enter its password.</li><li>Enter your broker&#39;s address as MQTT server (for the Home Assistant add-on, <code>homeassistant.local</code> or the server IP), keep port <code>1883</code>, and fill in the MQTT username and password from Step 1.</li><li>Click <strong>Save</strong>. The gateway restarts and joins your network.</li></ol><p>The full list of portal fields is described on the <a href="./upload/portal.html">configuration portal page</a>.</p><h2 id="step-4-—-check-that-it-works" tabindex="-1">Step 4 — Check that it works <a class="header-anchor" href="#step-4-—-check-that-it-works" aria-label="Permalink to &quot;Step 4 — Check that it works&quot;">​</a></h2><ul><li>In Home Assistant, go to <strong>Settings → Devices &amp; services → MQTT</strong>: after a minute you should see a device named <strong>OpenMQTTGateway</strong>, created automatically through MQTT discovery.</li><li><strong>Bluetooth</strong>: bring a compatible sensor nearby — it appears as its own device with its measurements as entities. Some devices only advertise on an event: press a button or trigger a reading if nothing shows up.</li><li><strong>RF</strong>: supported devices appear automatically as soon as they transmit — weather stations send every minute or two, door and PIR sensors on an event, so trigger one to see it arrive.</li><li>You can also watch the raw messages with <a href="https://mqtt-explorer.com/" target="_blank" rel="noreferrer">MQTT Explorer</a>: connect to your broker and look for <code>home/OpenMQTTGateway/LWT</code> = <code>online</code> and messages under <code>home/OpenMQTTGateway/</code>.</li></ul><p>Something not right? Head to the <a href="./upload/troubleshoot.html">troubleshooting page</a> or ask on the <a href="https://community.openmqttgateway.com" target="_blank" rel="noreferrer">community forum</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><strong>More RF options</strong> — other <a href="./upload/web-install.html?bridge=rf433">compatible boards and firmwares</a>, transmitting, frequency tuning, and protocol details in <a href="./setitup/rf.html">RF hardware setup</a> and <a href="./use/rf.html">RF usage</a>.</li><li><strong>Infrared</strong> — wire an IR emitter/receiver following the <a href="./setitup/ir.html">IR hardware setup</a>.</li><li><strong>Tune the gateway</strong> — the <a href="./use/webui.html">WebUI</a> and <a href="./use/gateway.html">gateway commands</a> let you configure it at runtime over MQTT.</li><li><strong>Other controllers</strong> — <a href="./integrate/openhab3.html">OpenHAB</a>, <a href="./integrate/node_red.html">Node-RED</a>, <a href="./integrate/jeedom.html">Jeedom</a>, <a href="./integrate/aws_iot.html">AWS IoT</a>.</li><li><strong>Full Home Assistant details</strong> — <a href="./integrate/home_assistant.html">Home Assistant integration</a>.</li></ul>',19))])}const w=r(l,[["render",h]]);export{f as __pageData,w as default};
